'use strict';
let sourceQuery='', sourceResults=null, networkResult=null, migrationResult=null, eventFilter='';
const networkNames=['material','mechanical','electrical','control','utility'];
function equipmentOptions(selected=''){return state.model.entities.filter(e=>e.canonical_id===e.id&&!e.inactive&&e.category!=='document').sort((a,b)=>a.label.localeCompare(b.label)).map(e=>`<option value="${esc(e.id)}" ${e.id===selected?'selected':''}>${esc(e.label)}</option>`).join('');}
function opsLink(text,hash){return `<a class="button secondary" href="#${hash}">${esc(text)}</a>`;}
function eventCards(items){return items.map(e=>`<article class="activity-row"><div class="inline-list">${badge(e.event_type,'blue')}${badge(e.current_status,e.current_status==='open'?'amber':'')}<button class="entity-button" data-action="equipment-page" data-id="${e.canonical_equipment}">${esc(label(e.canonical_equipment,state.model))}</button></div><h3>${esc(e.summary)}</h3><div class="sub">Occurred ${esc(fmt(e.occurred_at))} · recorded ${esc(fmt(e.recorded_at))}</div><p style="white-space:pre-wrap">${esc(e.details)}</p>${(e.measurements||[]).map(r=>`<p><strong>${esc(r.quantity)}: ${esc(r.value)} ${esc(r.unit)}</strong> ${esc(r.condition||'Condition unspecified')} ${esc(r.instrument||'')}</p>`).join('')}${e.related_event?`<div class="sub">Linked event: ${esc(e.related_event)}</div>`:''}<div class="inline-list">${(e.provenance.evidence||[]).map(s=>btn('Source','evidence',`data-id="${esc(s.evidence_id)}"`,'ghost small')).join('')}${btn('Add follow-up','event-followup',`data-id="${e.id}"`,'secondary small')}</div><span class="sub">${esc(e.id)}</span></article>`).join('')||'<div class="card-body muted">No records in this view yet.</div>';}
function operationsHome(){const records=state.events||[],open=records.filter(e=>e.current_status==='open');return heading('Operations desk','Find the evidence, trace documented connections, and retain what happened.',btn('Record shift / breakdown','new-event','',''))+`<div class="stats"><div class="stat"><div class="stat-top">Equipment identities</div><span class="stat-number">${state.model.entities.filter(e=>e.canonical_id===e.id&&!e.inactive&&e.category!=='document').length}</span><small>Reviewed plant model</small></div><div class="stat"><div class="stat-top">Open records</div><span class="stat-number">${open.length}</span><small>Reported issues and follow-ups</small></div><div class="stat"><div class="stat-top">Operational records</div><span class="stat-number">${records.length}</span><small>Observations, actions and outcomes</small></div><div class="stat"><div class="stat-top">Source documents</div><span class="stat-number">${state.documents.length}</span><small>Originals and evidence retained</small></div></div><div class="ops-questions"><a href="#sources"><strong>Where is the applicable source?</strong><span>Search documents, revisions and evidence.</span></a><a href="#networks"><strong>What connects to this equipment?</strong><span>Trace a documented network and inspect gaps.</span></a><a href="#log"><strong>What happened, and what needs attention?</strong><span>Review shift records and previous outcomes.</span></a></div><div class="inline-list" style="margin:20px 0">${opsLink('Equipment & evidence','knowledge')}${opsLink('Correct the working model','corrections')}${btn('Review existing data','load-migration','','secondary')}${btn('Add document','upload','','secondary')}${workspace==='demo'?btn('Next walkthrough sample','demo-next','','secondary'):''}</div><div class="ops-columns"><section class="card"><div class="card-head"><h2>Open issues and actions</h2></div>${eventCards(open.slice(0,8))}</section><section class="card"><div class="card-head"><h2>Recent operating history</h2></div>${eventCards(records.slice(0,8))}</section></div>`;}
function sourceSearchView(){return heading('Find source evidence','Search original text, names, revisions and page locators.')+`<form id="source-search-form" class="toolbar"><input id="source-query" aria-label="Search source evidence" class="search" value="${esc(sourceQuery)}" placeholder="Equipment tag, component or phrase" required maxlength="300"><button class="button">Search sources</button></form><p class="micro">All entered words must match. This searches extracted text; unreadable image text is not automatically indexed. Open the original drawing to inspect it.</p>${sourceResults?`<p>${sourceResults.total} matching evidence blocks${sourceResults.total>40?' · showing first 40':''}</p><section class="card">${sourceResults.results.map(s=>`<article class="activity-row"><h3>${esc(s.name)}</h3><div class="inline-list">${badge(s.revision||'Revision unknown')}${badge(s.authority)}</div><p class="sub">${esc(s.locator)} · page/sheet ${s.page}</p><p style="white-space:pre-wrap">${esc(s.snippet||'Image evidence; inspect page')}</p>${btn('Open evidence',s.support?'indexed-source':'evidence',`data-id="${s.id}" data-note="${s.index_note_id||''}"`,'secondary small')} ${btn('Open document','document',`data-id="${s.document_id}"`,'ghost small')}</article>`).join('')||'<div class="card-body">No exact matches. Try an alias or document name.</div>'}</section>`:''}`;}
function networkView(){return heading('Trace equipment connections','Separate networks with evidence for each connection.')+`<form id="network-form" class="card card-body"><div class="ops-form-grid"><label>Equipment<select id="network-equipment">${equipmentOptions(networkResult?.equipment||selectedEntity)}</select></label><label>Network<select id="network-kind">${networkNames.map(n=>`<option ${networkResult?.network===n?'selected':''}>${n}</option>`).join('')}</select></label><label>Direction<select id="network-direction"><option value="upstream" ${networkResult?.direction==='upstream'?'selected':''}>Upstream / supplying</option><option value="downstream" ${networkResult?.direction==='downstream'?'selected':''}>Downstream / supplied</option></select></label><label>Exact documented condition (optional)<input id="network-condition" value="${esc(networkResult?.condition||'')}" placeholder="For example: diverter to bunker A"></label></div><button class="button" style="margin-top:16px">Trace documented connections</button></form><div class="notice">Possible documented connections only. Unverified and conditional links are boundaries. This view does not establish live route state, complete coverage or isolation safety.</div>${networkResult?`<section class="card"><div class="card-head"><h2>${networkResult.paths.length} reachable items</h2>${badge('Coverage incomplete','amber')}</div>${networkResult.paths.map(p=>`<article class="activity-row"><strong>${esc(p.label)}</strong><p>${esc([label(networkResult.equipment,state.model),...p.steps.map(s=>label(s.to,state.model))].join(' → '))}</p>${p.steps.map(s=>`<div class="sub">${esc(s.predicate)} · ${esc(s.context.from_port||'port unspecified')} → ${esc(s.context.to_port||'port unspecified')} ${btn('Connection evidence','fact-source',`data-id="${s.assertion_id}" data-support="0"`,'ghost small')}</div>`).join('')}</article>`).join('')||'<div class="card-body">No documented paths found. Use the existing-data review to qualify supported relations; absence here does not mean no connection exists.</div>'}<div class="card-body"><h3>All traversed connections (${networkResult.edges.length})</h3>${networkResult.edges.map(a=>`<p>${esc(label(a.canonical_subject,state.model))} → ${esc(label(a.canonical_object,state.model))} ${btn('Evidence','fact-source',`data-id="${a.id}" data-support="0"`,'ghost small')}</p>`).join('')}<h3>Unresolved boundaries (${networkResult.excluded.length})</h3>${networkResult.excluded.map(x=>`<p>${esc(label(x.at,state.model))}: ${esc(x.reason)} ${esc(x.context.condition||'')}</p>`).join('')||'<p class="muted">No excluded links encountered. Missing undocumented links remain unknown.</p>'}</div></section>`:''}`;}
function logView(){const records=(state.events||[]).filter(e=>!eventFilter||[e.summary,e.details,label(e.canonical_equipment,state.model)].join(' ').toLowerCase().includes(eventFilter.toLowerCase()));return heading('Operating history','Observations, breakdowns, actions, outcomes and lessons.',btn('Add record','new-event','',''))+`<form id="event-filter-form" class="toolbar"><input id="event-filter" class="search" aria-label="Search operating history" value="${esc(eventFilter)}" placeholder="Equipment, symptom or repair"><button class="button secondary">Find previous cases</button></form><section class="card">${eventCards(records)}</section>`;}
function eventEditor(related=null){const equipment=related?.canonical_equipment||selectedEntity;const local=new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16);modal(related?'Record a follow-up':'Record shift / breakdown',`<form id="event-form"><div class="ops-form-grid"><label>Equipment<select id="event-equipment" required>${equipmentOptions(equipment)}</select></label><label>Record type<select id="event-type">${['observation','reading','breakdown','inspection','repair','replacement','action','outcome','lesson','correction'].map(t=>`<option ${t===(related?'outcome':'observation')?'selected':''}>${t}</option>`).join('')}</select></label><label>Occurred at (this computer’s local time)<input type="datetime-local" id="event-time" value="${local}" required></label><label>Status<select id="event-status"><option value="recorded">Recorded</option><option value="open">Open issue / action</option><option value="closed">Closed / resolved</option><option value="hypothesis">Hypothesis</option></select></label></div><label>Summary<input id="event-summary" maxlength="2000" required></label><label>Observations, readings with units, condition, action and outcome<textarea id="event-details" rows="6" maxlength="12000" required></textarea></label><details><summary>Add a structured reading (optional)</summary><div class="ops-form-grid"><label>Quantity<input id="reading-quantity" placeholder="bearing temperature"></label><label>Value<input id="reading-value" type="number" step="any"></label><label>Unit<input id="reading-unit" placeholder="degC"></label><label>Operating condition<input id="reading-condition"></label><label>Instrument<input id="reading-instrument"></label></div></details><label>Operator name<input id="event-author" maxlength="120" required></label>${related?`<p>Follow-up to ${esc(related.summary)} (${esc(related.id)}). Closing this follow-up updates that record’s displayed status.</p>`:''}<input type="hidden" id="event-related" value="${esc(related?.id||'')}"><p class="micro">Saving records your submitted observation with its time and source. It does not change equipment specifications. Lessons start as hypotheses.</p><div class="dialog-actions"><button class="button">Save operating record</button></div></form>`);$('#event-form').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{const type=$('#event-type').value;await api('/api/events',{expected_version:state.model.version,author:$('#event-author').value,reason:$('#event-details').value,event:{op:'event',equipment:$('#event-equipment').value,event_type:type,occurred_at:new Date($('#event-time').value).toISOString(),summary:$('#event-summary').value,details:$('#event-details').value,status:type==='lesson'?'hypothesis':$('#event-status').value,related_event:$('#event-related').value,measurements:$('#reading-quantity').value?[{quantity:$('#reading-quantity').value,value:$('#reading-value').value===''?null:Number($('#reading-value').value),unit:$('#reading-unit').value,...($('#reading-condition').value?{condition:$('#reading-condition').value}:{}),...($('#reading-instrument').value?{instrument:$('#reading-instrument').value}:{})}]:[]}});closeModal();await refresh(true);toast('Operating record saved with source and timestamp.');}catch(err){toast(err.message,true);button.disabled=false;}};}
function correctionsView(){return heading('Correct the working model','Stage corrections, inspect their scope, then accept them in Review changes.')+`<div class="notice">Extraction corrections and real plant changes are different. Invalidate only a proven false identity. Record a real replacement in operating history and update its supported equipment facts separately.</div><section class="card card-body"><form id="correction-form"><div class="ops-form-grid"><label>Equipment<select id="correction-equipment">${equipmentOptions(selectedEntity)}</select></label><label>Correction<select id="correction-kind"><option value="qualify">Qualify a fact / network connection</option><option value="retire">Retire an incorrect fact</option><option value="retract_alias">Retract an incorrect alias</option><option value="invalidate_entity">Invalidate a false entity</option><option value="advanced">Advanced batch / restore / unmerge</option></select></label></div><div id="correction-targets"></div><label>Evidence reviewed and correction reason<textarea id="correction-reason" rows="3" required maxlength="12000" placeholder="Identify the drawing/record, what was wrong, and what it supports."></textarea></label><label>Reviewer name<input id="correction-author" maxlength="120" required></label><button class="button" style="margin-top:16px">Preview correction in review queue</button></form></section><p class="micro">Qualifying a fact replaces its full context. Existing values, citations and earlier versions remain intact. For corrected values, stage retire + assert in Advanced batch. Reverse a mistaken merge before staging a split.</p>`;}
function correctionTargets(){const eid=$('#correction-equipment').value,kind=$('#correction-kind').value, facts=liveFacts(state.model).filter(a=>a.canonical_subject===eid);let body='';if(['qualify','retire'].includes(kind)){body=`<label>Active fact<select id="correction-fact">${facts.map(a=>`<option value="${a.id}">${esc(a.predicate+' = '+(a.canonical_object?label(a.canonical_object,state.model):JSON.stringify(a.value))+' '+(a.unit||''))}</option>`).join('')}</select></label>`;if(kind==='qualify')body+='<label>Complete operational context (JSON)<textarea id="correction-context" rows="9" class="json-editor"></textarea></label><p class="micro">For a verified directed connection: kind connection, network material/mechanical/electrical/control/utility, verification documented, optional from_port/to_port and condition. Do not guess dates or direction.</p>';}if(kind==='retract_alias')body=`<label>Alias<select id="correction-alias">${state.model.aliases.filter(a=>!a.retracted&&state.model.entities.find(e=>e.id===a.entity_id)?.canonical_id===eid).map(a=>`<option value="${a.id}">${esc(a.alias)} · ${esc(a.id)}</option>`).join('')}</select></label>`;if(kind==='invalidate_entity')body=`<p>This will hide ${esc(label(eid,state.model))}, its aliases and ${liveFacts(state.model).filter(a=>a.canonical_subject===eid||a.canonical_object===eid).length} connected facts from the working view. History remains available.</p>`;if(kind==='advanced')body=`<label>Operations JSON (provenance is attached from your submitted source note)<textarea id="correction-operations" rows="10" class="json-editor">[]</textarea></label><details><summary>Inactive and merged identities / retracted aliases</summary><pre class="source-text">${esc(JSON.stringify({entities:state.model.entities.filter(e=>e.inactive||e.canonical_id!==e.id).map(e=>({id:e.id,label:e.label,inactive:e.inactive,canonical_id:e.canonical_id})),aliases:state.model.aliases.filter(a=>a.retracted).map(a=>({alias_id:a.id,alias:a.alias,entity:a.entity_id}))},null,2))}</pre></details>`;$('#correction-targets').innerHTML=body;if(kind==='qualify'){const update=()=>{$('#correction-context').value=JSON.stringify(facts.find(a=>a.id===$('#correction-fact').value)?.context||{},null,2);};$('#correction-fact').onchange=update;update();}}
function migrationView(){if(!migrationResult)return heading('Existing-data review','Build a review list without altering committed facts.',btn('Inspect existing data','load-migration','',''));const m=migrationResult;return heading('Existing-data review',`Plant version ${m.version}. These are review candidates, not proven errors.`,btn('Refresh review list','load-migration','','secondary'))+`<div class="stats">${[['Facts needing context',m.missing_context.length],['Relations needing network review',m.network_review.length],['Quantities needing unit review',m.unsupported_units.length],['Entities without active facts',m.entities_without_active_facts.length]].map(([t,n])=>`<div class="stat"><div class="stat-top">${esc(t)}</div><span class="stat-number">${n}</span></div>`).join('')}</div><div class="inline-list">${opsLink('Stage corrections','corrections')}${btn('Download complete review list','migration-export','','secondary')}</div><p>Start with one operating route. Check identity and aliases, then quantities and conditions, then document connection direction. Unknown dates stay unknown. Preserve useful facts and all originals.</p>${[['Network review',m.network_review],['Missing context',m.missing_context],['Unit review',m.unsupported_units]].map(([title,items])=>`<section class="card"><div class="card-head"><h2>${title}</h2><span>Showing first 40 of ${items.length}</span></div>${items.slice(0,40).map(a=>`<div class="activity-row"><strong>${esc(a.equipment)}</strong> · ${esc(a.predicate)} · ${esc(a.unit||'')}<div class="sub">${esc(a.assertion_id)}</div>${btn('Inspect source','fact-source',`data-id="${a.assertion_id}" data-support="0"`,'ghost small')}</div>`).join('')}</section>`).join('')}<section class="card card-body"><h2>Entities without active facts</h2><p>${esc(m.entities_without_active_facts.map(e=>e.label).join(', ')||'None')}</p><p class="micro">An empty identity is not automatically an error. Verify before invalidating.</p></section>`;}
function bindOperations(){const s=$('#source-search-form');if(s)s.onsubmit=async e=>{e.preventDefault();sourceQuery=$('#source-query').value;try{sourceResults=await api('/api/search?q='+encodeURIComponent(sourceQuery));render();}catch(err){toast(err.message,true);}};const n=$('#network-form');if(n)n.onsubmit=async e=>{e.preventDefault();try{networkResult=await api('/api/network?'+new URLSearchParams({equipment:$('#network-equipment').value,network:$('#network-kind').value,direction:$('#network-direction').value,condition:$('#network-condition').value}));render();}catch(err){toast(err.message,true);}};const f=$('#event-filter-form');if(f)f.onsubmit=e=>{e.preventDefault();eventFilter=$('#event-filter').value;render();};const c=$('#correction-form');if(c){correctionTargets();$('#correction-equipment').onchange=correctionTargets;$('#correction-kind').onchange=correctionTargets;c.onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{const kind=$('#correction-kind').value,reason=$('#correction-reason').value;let ops;if(kind==='advanced')ops=JSON.parse($('#correction-operations').value);else{const op={op:kind,reason};if(kind==='qualify'||kind==='retire')op.assertion_id=$('#correction-fact').value;if(kind==='qualify')op.context=JSON.parse($('#correction-context').value);if(kind==='retract_alias')op.alias_id=$('#correction-alias').value;if(kind==='invalidate_entity')op.entity=$('#correction-equipment').value;ops=[op];}const r=await api('/api/corrections',{expected_version:state.model.version,author:$('#correction-author').value,reason,operations:ops});await refresh();selectedProposal=r.proposal_id;location.hash='review';render();toast('Correction staged. Inspect the source and operations before accepting.');}catch(err){toast(err.message,true);button.disabled=false;}};}}
async function operationsAction(name,el){const id=el.dataset.id;if(name==='indexed-source'){const r=sourceResults.results.find(s=>s.index_note_id===el.dataset.note&&s.id===id);await source(r.support);return true;}if(name==='new-event'){eventEditor();return true;}if(name==='event-followup'){eventEditor(state.events.find(e=>e.id===id));return true;}if(name==='equipment-page'){selectedEntity=id;historical=null;location.hash='overview?equipment='+encodeURIComponent(id);render();return true;}if(name==='load-migration'){migrationResult=await api('/api/migration');location.hash='migration';render();return true;}if(name==='migration-export'){await download('/api/migration','chp-existing-data-review.json');return true;}return false;}
